from collections.abc import Mapping, Sequence
from math import hypot, isfinite
from numbers import Real


def _finite_number(value, name):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise TypeError(f"{name} must be a real number")
    if not isfinite(value):
        raise ValueError(f"{name} must be finite")
    return float(value)


def _integer(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    return value


def route_length(points):
    if isinstance(points, (str, bytes)) or not isinstance(points, Sequence):
        raise TypeError("points must be a sequence")
    copied = []
    for point in points:
        if isinstance(point, (str, bytes)) or not isinstance(point, Sequence) or len(point) != 2:
            raise TypeError("each point must contain two coordinates")
        copied.append((_finite_number(point[0], "x"), _finite_number(point[1], "y")))
    return sum(abs(x2 - x1) + abs(y2 - y1) for (x1, y1), (x2, y2) in zip(copied, copied[1:]))


def estimate_charge(coefficients, year, slot, points, item_count):
    if not isinstance(coefficients, Mapping):
        raise TypeError("coefficients must be a mapping")
    required = {"base", "year", "slot", "distance", "items"}
    if set(coefficients) != required:
        raise ValueError("coefficients must contain exactly the required keys")
    values = {key: _finite_number(coefficients[key], key) for key in required}
    year = _integer(year, "year")
    slot = _integer(slot, "slot")
    item_count = _integer(item_count, "item_count")
    if not 0 <= slot <= 23:
        raise ValueError("slot must be between 0 and 23")
    if item_count < 0:
        raise ValueError("item_count cannot be negative")
    result = (values["base"] + values["year"] * year + values["slot"] * slot +
              values["distance"] * route_length(points) + values["items"] * item_count)
    if not isfinite(result):
        raise ValueError("result must be finite")
    return result

